function assessWikiCompletion(body,work,manifest,events){
 const id=String(body?.work_id||"");
 const fail=reason=>({ok:false,stage:"wiki_complete_gate",work_id:id,reason});
 if(!work||!work.id||work.work_id!==id||work.kind!=="wiki_compile"||work.status!=="processing"||work.worker!=="hourly")return fail("work_not_processing_wiki_compile");
 if(!String(work.source_event_id||"").startsWith("knowledge.promotion.manifest:"))return fail("source_manifest_ref_invalid");
 if(!manifest||manifest.event_id!==work.source_event_id||manifest.category!=="knowledge.promotion.manifest"||manifest.status!=="approved"||manifest.project!=="agentic-work-atlas"||manifest.correlation_id!==work.correlation_id)return fail("promotion_manifest_missing_or_mismatched");
 let mf;try{mf=JSON.parse(String(manifest.metadata_object||""))}catch{return fail("promotion_manifest_json_invalid")}
 if(mf.decision!=="promote"||mf.execution_policy!=="chatgpt_direct_only"||!String(mf.canonical_key||"").trim()||!String(mf.promotion_id||"").trim()||!String(mf.accepted_scope||"").trim()||!mf.success_criteria)return fail("promotion_manifest_contract_invalid");
 const ref=String(body.result_ref||"");
 const matches=[];
 for(const e of events){
  if(!e?.event_id||e.correlation_id!==work.correlation_id||e.project!=="agentic-work-atlas")continue;
  const legacy=e.category==="knowledge.integration.completed"&&e.status==="completed"&&e.event_id.startsWith("knowledge.integration.completed:");
  const current=e.category==="knowledge.integration.result"&&["compiled","completed","no_delta","duplicate"].includes(e.status)&&e.event_id.startsWith("knowledge.integration:");
  if(!legacy&&!current)continue;
  let m;try{m=JSON.parse(String(e.metadata_object||""))}catch{continue}
  if(m.work_id!==id||m.source_event_id!==work.source_event_id||m.canonical_key!==mf.canonical_key||m.promotion_id!==mf.promotion_id)continue;
  const outcome=String(m.result||"");
  if(outcome==="compiled"){
   if(!/^git:[0-9a-f]{40}$/i.test(ref)||String(m.commit||"").toLowerCase()!==ref.slice(4).toLowerCase()||m.push_verified!==true||Number(m.lint_blocking??m.wiki_lint_blocking)!==0)continue;
   if(!Array.isArray(m.wiki_paths)||!m.wiki_paths.length||!m.wiki_paths.every(p=>typeof p==="string"&&p.startsWith("wiki/")&&p.endsWith(".md")))continue;
   if(!(legacy||e.status==="compiled"))continue;
  }else if(outcome==="no_delta"||outcome==="duplicate"){
   if(!current||e.status!==outcome||ref!==`work_events:${e.event_id}`||m.no_repository_write!==true||!String(m.decision_basis||"").trim())continue;
   if(!Array.isArray(m.checked_wiki_paths)||m.checked_wiki_paths.length<1||!m.checked_wiki_paths.every(p=>typeof p==="string"&&p.startsWith("wiki/")&&p.endsWith(".md")))continue;
   if(m.commit||m.push_verified===true)continue;
  }else continue;
  matches.push({event_id:e.event_id,result:outcome,commit:outcome==="compiled"?ref.slice(4):""});
 }
 if(matches.length!==1)return fail(matches.length?"ambiguous_integration_events":"matching_integration_evidence_missing");
 return {ok:true,stage:"wiki_complete_gate",work_id:id,result:matches[0].result,commit:matches[0].commit,integration_event_id:matches[0].event_id};
}
const body=$('Complete AI Work').first().json.body;
const work=$('Read Completion Work').first().json;
const manifest=$('Read Wiki Completion Manifest').first().json;
const events=$input.all().map(i=>i.json);
return [{json:assessWikiCompletion(body,work,manifest,events)}];

